#include <bits/stdc++.h>
using namespace std;
class Solution {public:int countPairs(vector<vector<int>>& coordinates,int k){unordered_map<long long,int> freq;long long ans=0;for(auto&p:coordinates){int x=p[0],y=p[1];for(int a=0;a<=k;++a){int xx=x^a,yy=y^(k-a);long long key=((long long)xx<<32)|(unsigned)yy;ans+=freq[key];}long long key=((long long)x<<32)|(unsigned)y;++freq[key];}return (int)ans;}};
